 Context context;Path out=Path.of("build/reports/rucesion-v157");
 @Before public void reset(){context=RuntimeEnvironment.getApplication();for(String s:new String[]{"project_dark_f5m_v1","project_dark_skill_book_v1","project_dark_skill_test_v1"})context.getSharedPreferences(s,0).edit().clear().commit();F5mSaveStore.install(context);}
 void save(Bitmap b,String n)throws Exception{Files.createDirectories(out);try(java.io.OutputStream stream=Files.newOutputStream(out.resolve(n+".png"))){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,stream));}}
 void change(GameView v,String id)throws Exception{Method m=GameView.class.getDeclaredMethod("changeCampaignMap",String.class,boolean.class);m.setAccessible(true);m.invoke(v,id,false);}
 @Test public void sourceLevelsAreSeparateFromProvisionalMaximumAndBossRemainsPreviewOnly(){assertEquals(10,RucesionCoastMonsters.ALL.size());assertEquals(Integer.valueOf(82),RucesionCoastMonsters.observedLevel("LYK_BLUE_HACON"));assertNull(RucesionCoastMonsters.observedLevel("LYK_RED_HACON"));assertEquals(Integer.valueOf(98),RucesionCoastMonsters.observedLevel("LYK_TYRANT"));assertNull(new MonsterDefinitionRegistry().resolve("LYK_BLUE_HACON").hp);assertFalse(CampaignWorld.canEnter(RucesionCoastGeometry.ENTRY,70,true));assertTrue(CampaignWorld.canEnter(RucesionCoastGeometry.ENTRY,71,false));assertFalse(CampaignWorld.canEnter(RucesionCoastGeometry.BOSS,99,true));assertEquals(0,RucesionCombatProfiles.forId("LYK_ARIEL").exp);}
 @Test public void allScenesHaveFullPopulationLegalSeparatedSpawnsAndConnectedGates(){Set<String> ids=new HashSet<>();for(String map:RucesionCoastGeometry.ROUTE){RuntimeState s=new RuntimeState();s.enterCampaignMap(map,false);PoteCampaignMapDef d=PoteCampaignMapDef.forId(map);Set<String> cells=new HashSet<>();for(WorldMoveTargetController.TileCenter t:CampaignWorld.connectedTiles(map))cells.add(Math.round(t.x)+":"+Math.round(t.y));assertTrue(cells.size()>(RucesionCoastGeometry.ENTRY.equals(map)?250:2000));for(WorldMoveTargetController.TileCenter t:Arrays.asList(CampaignWorld.arrival(map,false),CampaignWorld.arrival(map,true),CampaignWorld.forward(map),CampaignWorld.backward(map))){assertTrue(cells.contains(Math.round(t.x)+":"+Math.round(t.y)));assertFalse(d.terrainBlocked(t.x,t.y,10));}int z=RucesionCoastGeometry.index(map);assertEquals(z==0?0:z==4?8:z==1?65:86,s.monsters().size());Set<String> arts=new HashSet<>();for(RuntimeState.Monster m:s.monsters()){ids.add(m.campaignRewardProfileId);arts.add(PoteForestMonsterShowcase.artKey(m.id));assertTrue(cells.contains(Math.round(m.x)+":"+Math.round(m.y)));assertFalse(d.terrainBlocked(m.x,m.y,14));assertTrue(Math.hypot(m.x-s.player().x,m.y-s.player().y)>170);}assertTrue(arts.size()<=5);for(int i=0;i<s.monsters().size();i++)for(int j=0;j<i;j++)assertTrue(Math.hypot(s.monsters().get(i).x-s.monsters().get(j).x,s.monsters().get(i).y-s.monsters().get(j).y)>=100);}assertEquals(new HashSet<>(RucesionCoastMonsters.ALL),ids);}
 @Test public void realTownNpcPreviewAndReturnDoNotGrantLevelsOrRewards()throws Exception{GameView v=new GameView(context);v.layout(0,0,960,540);TownInteriorTest.call(v,"enterPoteField");change(v,RucesionTownGeometry.ID);RuntimeState s=TownInteriorTest.field(v,"state");long exp=CampaignProgress.earnedExp(s.rpg()),gold=s.rpg().gold();RuntimeState.Npc n=s.npcs().stream().filter(a->a.id.equals("rucesion_beach_keeper")).findFirst().get();WorldRuntimeAdapter w=TownInteriorTest.field(v,"poteFieldAdapter");assertTrue(CampaignNavigationTest.walk(w,w.requestNpcApproach(n.id)));InteractionController i=TownInteriorTest.field(v,"interaction");assertEquals(InteractionController.TickResult.DIALOG_OPENED,i.request(s,n));TownInteriorTest.tap(v,667,429);assertEquals(RucesionTownGeometry.ID,s.currentMapId());v.setSkillTestMode(true);assertEquals(InteractionController.TickResult.DIALOG_OPENED,i.request(s,n));Bitmap dialog=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);v.draw(new Canvas(dialog));save(dialog,"town-beach-dialogue");TownInteriorTest.tap(v,667,429);assertEquals(RucesionCoastGeometry.ENTRY,s.currentMapId());assertEquals(exp,CampaignProgress.earnedExp(s.rpg()));assertEquals(gold,s.rpg().gold().longValue());w=TownInteriorTest.field(v,"poteFieldAdapter");WorldMoveTargetController.TileCenter back=CampaignWorld.backward(s.currentMapId());assertTrue(CampaignNavigationTest.walk(w,w.requestGroundWorld(back.x,back.y)));TownInteriorTest.tick(v,1);assertEquals(RucesionTownGeometry.ID,s.currentMapId());assertFalse(s.blocked(s.player().x,s.player().y));}
 @Test public void exactSaveRestoresEverySceneAtLegalPosition()throws Exception{GameView v=new GameView(context);v.layout(0,0,960,540);TownInteriorTest.call(v,"enterPoteField");v.setSkillTestMode(true);for(String map:RucesionCoastGeometry.ROUTE){change(v,map);RuntimeState s=TownInteriorTest.field(v,"state");assertTrue(F5mSaveStore.checkpointActive());float x=s.player().x,y=s.player().y;F5mSaveStore.install(context);GameView fresh=new GameView(context);RuntimeState r=TownInteriorTest.field(fresh,"state");assertEquals(map,r.currentMapId());assertEquals(x,r.player().x,.01);assertEquals(y,r.player().y,.01);F5mSaveStore.bindRuntime(s,TownInteriorTest.field(v,"f5mQuest"),TownInteriorTest.field(v,"quest2"));}}
 @Test public void all120PackagedFramesAreUniqueTransparentAndDrawWithCorrectRegistration()throws Exception{PoteFieldRenderer renderer=new PoteFieldRenderer();Bitmap sheet=Bitmap.createBitmap(1000,3500,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(sheet);c.drawColor(0xffc4a77b);int row=0;for(String id:RucesionCoastMonsters.ALL){Set<Integer> unique=new HashSet<>();int pose=0;for(String p:new String[]{"idle","walk","attack"}){int col=0;for(CharacterRenderer.Direction d:CharacterRenderer.Direction.values()){Bitmap b=BitmapFactory.decodeStream(context.getAssets().open(PoteForestMonsterShowcase.assetPath(id,p,d)));assertNotNull(b);assertEquals(192,b.getWidth());assertEquals(192,b.getHeight());int[] px=new int[192*192];b.getPixels(px,0,192,0,0,192,192);unique.add(Arrays.hashCode(px));for(int j=0;j<192;j++){assertEquals(0,b.getPixel(j,0)>>>24);assertEquals(0,b.getPixel(j,191)>>>24);assertEquals(0,b.getPixel(0,j)>>>24);assertEquals(0,b.getPixel(191,j)>>>24);}renderer.drawMonsterTestPose(c,id,p,d,.6f,.4f,110+col++*245,row*350+pose*108+106);}pose++;}assertEquals(id,12,unique.size());row++;}save(sheet,"all120-native-poses");}
 @Test public void nativeScenesTwelveTripsAndWarmFloorStayWithinAcceptedCacheBudgets()throws Exception{PoteFieldRenderer r=new PoteFieldRenderer();List<Double> times=new ArrayList<>();int pairsMax=0;for(int trip=0;trip<12;trip++){String map=RucesionCoastGeometry.ROUTE[trip%5];RuntimeState s=new RuntimeState();s.enterCampaignMap(map,false);WorldRuntimeAdapter w=CampaignNavigationTest.adapter(s);r.prepareMonsters(s);int pairs=((Map<?,?>)ForestPixelCacheTest.field(r,"hitCache")).size();pairsMax=Math.max(pairsMax,pairs);assertTrue(pairs<=60);for(int spot=0;spot<3;spot++){w.camera().snapTo(640+spot*950,spot==2?1550:800);Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);List<PoteFieldRenderer.ActorDraw> actors=new ArrayList<>();for(RuntimeState.Monster m:s.monsters()){WorldCameraTransform.Point at=w.worldToScreen(m.x,m.y);actors.add(new PoteFieldRenderer.ActorDraw(m.x,m.y,PoteForestMonsterShowcase.bodyHeight(m.id),52,()->r.drawMonster(c,m,at.x,at.y)));}r.drawScene(c,w,actors);long cold=((Number)ForestPixelCacheTest.field(r,"floorChunkBuilds")).longValue();for(int f=0;f<6;f++){long now=System.nanoTime();r.drawScene(c,w,actors);times.add((System.nanoTime()-now)/1e6);}assertEquals(cold,((Number)ForestPixelCacheTest.field(r,"floorChunkBuilds")).longValue());assertTrue(((Map<?,?>)ForestPixelCacheTest.field(r,"floorChunks")).size()<=32);if(trip<5)save(b,map+"-spot"+spot);b.recycle();}}Collections.sort(times);Files.createDirectories(out);Files.write(out.resolve("performance.json"),new org.json.JSONObject().put("scope","Robolectric renderer CPU, not handsetFPS").put("p95Ms",times.get((int)Math.ceil(times.size()*.95)-1)).put("p99Ms",times.get((int)Math.ceil(times.size()*.99)-1)).put("maxMs",times.get(times.size()-1)).put("sourceHitPairsMax",pairsMax).put("floorPixelBound",8652800).put("trips",12).toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 @Test public void allTenSpeciesUseActualResolverAndExactlyOnceDurableRewards()throws Exception{for(String id:RucesionCoastMonsters.ALL){reset();RuntimeState s=new RuntimeState();AbelCoastV139Test.restoreD04(s.rpg(),"WARRIOR");String map=null;for(String p:RucesionCoastGeometry.ROUTE)if(RucesionCoastMonsters.roster(p).contains(id)){map=p;break;}s.enterCampaignMap(map,false);CampaignProgressTest.allocate(s.rpg(),"WARRIOR");s.applyDerivedGrowth();CampaignResources.freeRest(s);RuntimeState.Monster m=s.monsters().stream().filter(a->a.campaignRewardProfileId.equals(id)).findFirst().get();assertEquals(RucesionCombatProfiles.forId(id).hp,m.maxHp);m.hp=1; // final-contact plumbing fixture, not fullHP balance proof
  SkillBook b=SkillBook.load(context);b.bindJob(s.rpg()::currentJobCode);RuntimeCombatSession session=new RuntimeCombatSession(s,(a,t)->true,(a,k)->b.usable(k),a->true);F5mSaveStore.bindRuntime(s,F5mAdaptedPrologueQuest.openingFixture(),new GrowthQuest2());F5mSaveStore.restoreAndBindSkillsActive(b);long exp=CampaignProgress.earnedExp(s.rpg());CampaignProgressTest.kill(s,session,b,m,null);assertEquals(exp+RucesionCombatProfiles.forId(id).exp,CampaignProgress.earnedExp(s.rpg()));assertEquals(1,s.rpg().rewardHistory().size());s.rpg().consumeCombat(s.ledger().snapshot(),s);assertEquals(1,s.rpg().rewardHistory().size());assertTrue(F5mSaveStore.checkpointActive());F5mSaveStore.install(context);RpgProgressionState restored=new RpgProgressionState();F5mSaveStore.restoreRewardsActive(restored);assertEquals(CampaignProgress.earnedExp(s.rpg()),CampaignProgress.earnedExp(restored));}}
